INSERT INTO `wp_arsenal_sponsors` VALUES (1,'Lamborgini','Крупнейший промышленный холдинг Минской области. Генеральный спонсор клуба с 2018 года. Компания активно поддерживает развитие спорта в регионе и инвестирует в модернизацию инфраструктуры стадиона.','partner','Промышленность','http://arsenal.test/wp-content/uploads/2026/01/lamba.png','',1,1,'2026-01-13 07:52:29','2026-01-13 11:10:40'),(2,'Porsche','Официальный поставщик спортивной экипировки и формы команды. Сотрудничество с 2019 года.','partner','Спортивная экипировка','http://arsenal.test/wp-content/uploads/2026/01/porshe.png','',1,1,'2026-01-13 07:52:29','2026-01-13 08:36:53'),(3,'Энергетик','Региональная энергетическая компания. Обеспечивает стадион электроэнергией и поддерживает молодежные программы клуба.','partner','Энергетика',NULL,NULL,1,2,'2026-01-13 07:52:29','2026-01-16 12:13:30'),(4,'АвтоБел','Крупнейший автодилер региона. Предоставляет транспортные услуги для команды на выездные матчи.','partner','Автомобили',NULL,NULL,1,3,'2026-01-13 07:52:29','2026-01-16 12:13:22'),(5,'БелБанк','Официальный банковский партнер клуба. Обеспечивает финансовые услуги и поддержку болельщицких программ.','partner','Банковские услуги',NULL,NULL,1,4,'2026-01-13 07:52:29','2026-01-16 12:10:19'),(6,'МедиаГруп','Медиахолдинг, освещающий все матчи клуба. Производит видеоконтент и ведет трансляции домашних игр.','partner','Медиа',NULL,NULL,1,5,'2026-01-13 07:52:29','2026-01-16 12:13:17'),(7,'Alfa Romeo','','partner','Авто','http://arsenal.test/wp-content/uploads/2026/01/alfa.png','',1,0,'2026-01-13 09:07:14','2026-01-13 11:14:26'),(8,'Audi','Самые крутые тачки в мире','general_sponsor','Авто','http://arsenal.test/wp-content/uploads/2026/01/Audi.png','',1,0,'2026-01-13 09:09:33','2026-01-13 11:14:26');
