DROP TABLE IF EXISTS `wp_arsenal_staff`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_arsenal_staff` (
  `id` int NOT NULL AUTO_INCREMENT,
  `first_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `second_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `department_id` int DEFAULT NULL,
  `job_title_id` int DEFAULT NULL,
  `squad_id` tinyint unsigned DEFAULT NULL,
  `birth_date` date DEFAULT NULL,
  `contract_start` date DEFAULT NULL,
  `contract_end` date DEFAULT NULL,
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `photo_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bio` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `achievements` json DEFAULT NULL,
  `career_positions` json DEFAULT NULL COMMENT 'История должностей и опыта: {title, organization, experience}',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `experience` int DEFAULT '0',
  `citizenship` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `interesting_fact` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Интересный факт о сотруднике',
  `sort_order` int DEFAULT '0' COMMENT 'Порядок сортировки персонала',
  PRIMARY KEY (`id`),
  KEY `idx_first_name` (`first_name`),
  KEY `idx_second_name` (`second_name`),
  KEY `idx_job_title_id` (`job_title_id`),
  KEY `fk_staff_department_id` (`department_id`),
  KEY `fk_arsenal_staff_squad` (`squad_id`),
  KEY `idx_sort_order` (`sort_order`),
  CONSTRAINT `fk_arsenal_staff_squad` FOREIGN KEY (`squad_id`) REFERENCES `wp_arsenal_squad` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_staff_department_id` FOREIGN KEY (`department_id`) REFERENCES `wp_arsenal_staff_department` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_staff_job_title` FOREIGN KEY (`job_title_id`) REFERENCES `wp_arsenal_staff_job_titles` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
