--
-- Table structure for table `wp_arsenal_matches`
--

DROP TABLE IF EXISTS `wp_arsenal_matches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_arsenal_matches` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `match_id` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `abbf_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tour` tinyint unsigned NOT NULL,
  `season_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `league_id` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tournament_id` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `match_date` date NOT NULL,
  `match_time` time DEFAULT NULL,
  `home_team_id` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `away_team_id` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `home_score` tinyint unsigned DEFAULT NULL,
  `away_score` tinyint unsigned DEFAULT NULL,
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `stadium_id` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `attendance` int unsigned DEFAULT NULL,
  `main_referee` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `match_report` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `assistant_referees_1` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assistant_referees_2` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fourth_referee` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `referee_inspector` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delegate` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `match_id` (`match_id`),
  UNIQUE KEY `abbf_url` (`abbf_url`),
  KEY `idx_match_id` (`match_id`),
  KEY `idx_tour` (`tour`),
  KEY `idx_match_date` (`match_date`),
  KEY `idx_home_team_id` (`home_team_id`),
  KEY `idx_away_team_id` (`away_team_id`),
  KEY `idx_stadium_id` (`stadium_id`),
  KEY `wp_arsenal_matches_tournament_fk` (`league_id`),
  KEY `fk_matches_status` (`status`),
  KEY `fk_matches_season_id` (`season_id`),
  KEY `idx_league_id` (`league_id`),
  KEY `idx_tournament_id` (`tournament_id`),
  CONSTRAINT `fk_matches_away_team` FOREIGN KEY (`away_team_id`) REFERENCES `wp_arsenal_teams` (`team_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_matches_home_team` FOREIGN KEY (`home_team_id`) REFERENCES `wp_arsenal_teams` (`team_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_matches_league_id` FOREIGN KEY (`league_id`) REFERENCES `wp_arsenal_leagues` (`league_id`),
  CONSTRAINT `fk_matches_season_id` FOREIGN KEY (`season_id`) REFERENCES `wp_arsenal_seasons` (`season_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_matches_stadiums` FOREIGN KEY (`stadium_id`) REFERENCES `wp_arsenal_stadiums` (`stadium_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_matches_statuses` FOREIGN KEY (`status`) REFERENCES `wp_arsenal_match_statuses` (`status_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_matches_tournament_id` FOREIGN KEY (`tournament_id`) REFERENCES `wp_arsenal_tournaments` (`tournament_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1514 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Матчи - основная таблица с результатами, датами, стадионами';
/*!40101 SET character_set_client = @saved_cs_client */;

