--
-- Table structure for table `wp_arsenal_match_lineups`
--

DROP TABLE IF EXISTS `wp_arsenal_match_lineups`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_arsenal_match_lineups` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `match_id` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `team_id` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `player_id` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `shirt_number` tinyint unsigned DEFAULT NULL,
  `is_captain` tinyint(1) DEFAULT '0',
  `is_starting` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_match_id` (`match_id`),
  KEY `idx_team_id` (`team_id`),
  KEY `idx_player_id` (`player_id`),
  KEY `idx_match_team` (`match_id`,`team_id`),
  CONSTRAINT `fk_match_lineups_matches` FOREIGN KEY (`match_id`) REFERENCES `wp_arsenal_matches` (`match_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_match_lineups_players` FOREIGN KEY (`player_id`) REFERENCES `wp_arsenal_players` (`player_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_match_lineups_teams` FOREIGN KEY (`team_id`) REFERENCES `wp_arsenal_teams` (`team_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=57950 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Составы матча - стартовый и запасные игроки по позициям';
/*!40101 SET character_set_client = @saved_cs_client */;

