--
-- Table structure for table `wp_arsenal_player_stats_corrections`
--

DROP TABLE IF EXISTS `wp_arsenal_player_stats_corrections`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_arsenal_player_stats_corrections` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `correction_id` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Уникальный ID корректировки',
  `player_id` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ID игрока (связь с wp_arsenal_players)',
  `tournament_id` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ID турнира (связь с wp_arsenal_tournaments)',
  `season_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ID сезона (опционально, связь с wp_arsenal_seasons)',
  `minutes_played_delta` int DEFAULT '0' COMMENT 'Корректировка минут за сезон (+/- значение)',
  `matches_played_delta` int DEFAULT '0' COMMENT 'Корректировка матчей сыграно',
  `goals_delta` int DEFAULT '0' COMMENT 'Корректировка голов забито',
  `goals_conceded_delta` int DEFAULT '0' COMMENT 'Корректировка голов пропущено (для вратарей)',
  `assists_delta` int DEFAULT '0' COMMENT 'Корректировка ассистов',
  `yellow_cards_delta` int DEFAULT '0' COMMENT 'Корректировка жёлтых карточек',
  `red_cards_delta` int DEFAULT '0' COMMENT 'Корректировка красных карточек',
  `correction_reason` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Причина корректировки (пример: "Ошибка парсера", "Пересчёт статистики")',
  `is_applied` tinyint(1) DEFAULT '0' COMMENT 'Применена ли корректировка к основной статистике (0=нет, 1=да)',
  `applied_at` datetime DEFAULT NULL COMMENT 'Дата и время применения корректировки',
  `applied_by` int unsigned DEFAULT NULL COMMENT 'ID пользователя WordPress, применившего корректировку (FK на wp_users)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Дата создания записи о корректировке',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Дата последнего обновления',
  PRIMARY KEY (`id`),
  UNIQUE KEY `correction_id` (`correction_id`),
  KEY `idx_player_id` (`player_id`),
  KEY `idx_tournament_id` (`tournament_id`),
  KEY `idx_season_id` (`season_id`),
  KEY `idx_is_applied` (`is_applied`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_player_tournament` (`player_id`,`tournament_id`),
  KEY `idx_applied_at` (`applied_at`),
  CONSTRAINT `fk_stats_corr_player_id` FOREIGN KEY (`player_id`) REFERENCES `wp_arsenal_players` (`player_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_stats_corr_season_id` FOREIGN KEY (`season_id`) REFERENCES `wp_arsenal_seasons` (`season_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_stats_corr_tournament_id` FOREIGN KEY (`tournament_id`) REFERENCES `wp_arsenal_tournaments` (`tournament_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Таблица для хранения ручных корректировок статистики игроков';
/*!40101 SET character_set_client = @saved_cs_client */;

