  `comment` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Детальный комментарий с обоснованием',
  `applied_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Дата применения корректировки',
