  CONSTRAINT `fk_standings_adjustments_team` FOREIGN KEY (`team_id`) REFERENCES `wp_arsenal_teams` (`team_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_standings_adjustments_tournament` FOREIGN KEY (`tournament_id`) REFERENCES `wp_arsenal_tournaments` (`tournament_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Корректировки турнирной таблицы (штрафы и бонусы команд)';
